-- PlayCrows V1 Event007: New Multi-Language Client Promotion
-- Draft event. EN/PT/TH require 5 promotion links; KO/TW/RU require 10.
-- Uses the latest V1 PC and Android client links supplied for September 2026.
-- Idempotent: updates an existing V1 Event007 if present, otherwise inserts it.

do $$
declare
  v_event_id uuid;
begin
  select id into v_event_id
  from public.events
  where server = 'v1'
    and regexp_replace(event_number, '^0+', '') = '7'
  order by created_at desc
  limit 1;

  if v_event_id is null then
    insert into public.events (
      server, slug, event_number, title, short_description, description,
      mechanics, rewards, form_fields, translations, action_links,
      status, starts_at, ends_at, published_at,
      claim_frequency, weekly_reset_day, weekly_reset_hour, weekly_reset_timezone,
      require_character_name, require_player_id, created_at, updated_at
    ) values (
      'v1',
      'event-007',
      '007',
      $title$🌐 EVENT007 — NEW MULTI-LANGUAGE CLIENT PROMOTION$title$,
      $short$Show one of the latest V1 updates and help promote the new PlayCrows V1 Multi-Language Client.$short$,
      $desc$Take an in-game screenshot of one of the newly released PlayCrows V1 updates, use the recruitment message, and promote the latest V1 Multi-Language Client.$desc$,
      $mechanics$["Take an in-game screenshot using your own PlayCrows V1 character that clearly shows at least ONE of the newly released V1 updates.","Accepted examples include Tower of Trial, the Class Change System, the updated CREED maximum limit, the updated Skill Trait Tome limit, or another newly released V1 feature.","Create a recruitment/promotional post using your screenshot and the PlayCrows V1 Multi-Language Client recruitment message.","Your recruitment post must include the latest V1 PC and Android Multi-Language Client download links.","Post the promotion in 5 different active gaming communities. Night Crows or MMORPG-related communities are preferred.","All 5 community posts must be public and remain accessible until your claim has been reviewed.","Duplicate, private, deleted, inaccessible, spam, inactive, unrelated, or unverifiable posts will not be accepted."]$mechanics$::jsonb,
      $rewards$["Draught of Vigilance (Bound) ×30","Star's Memory (Bound) ×450","Torn Invoices (Attribution) ×50","Torn Seniority Letter (Attribution) ×50","[C] Crafting Material x40 Selection Chest (Bound) ×50","Ancient Papyrus (Bound) ×500","Wind Orb Chest (Attributed) ×10"]$rewards$::jsonb,
      $fields$[{"id":"event007_promotion_links","type":"links","label":"Promotion Post Links","helpText":"Submit the 5 direct links where you posted the PlayCrows V1 Multi-Language Client promotion.","minItems":5,"maxItems":5,"required":true,"placeholder":"https://…"}]$fields$::jsonb,
